package dev.eigenworks.client.screen;
import dev.eigenworks.automation.FactoryCellMenu;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public final class FactoryCellScreen extends AbstractContainerScreen<FactoryCellMenu>{public FactoryCellScreen(FactoryCellMenu m,Inventory i,Component t){super(m,i,t,290,190);titleLabelX=10;titleLabelY=8;}@Override protected void init(){super.init();addRenderableWidget(b("Insert item",leftPos+12,topPos+130,78,0));addRenderableWidget(b("E-Stop",leftPos+96,topPos+130,65,1));addRenderableWidget(b("Scan period",leftPos+167,topPos+130,85,2));}private Button b(String s,int x,int y,int w,int id){return Button.builder(Component.literal(s),q->{if(minecraft!=null&&minecraft.gameMode!=null)minecraft.gameMode.handleInventoryButtonClick(menu.containerId,id);}).bounds(x,y,w,20).build();}@Override public void extractBackground(GuiGraphicsExtractor g,int x,int y,float p){g.fill(leftPos,topPos,leftPos+290,topPos+190,0xF00B1117);g.outline(leftPos,topPos,290,190,0xFF4DB6AC);}@Override protected void extractLabels(GuiGraphicsExtractor g,int x,int y){g.text(font,title,10,8,0xFF76E5D8,false);g.text(font,"INPUT IMAGE",12,30,0xFFB4E1DC,false);g.text(font,"Photo: "+menu.photo()+"   Proximity: "+menu.proximity(),12,47,0xFFE5E9F0,false);g.text(font,"Emergency stop: "+menu.estop(),12,63,menu.estop()?0xFFFF6868:0xFF72E572,false);g.text(font,"OUTPUT IMAGE",12,83,0xFFB4E1DC,false);g.text(font,"Conveyor: "+menu.conveyor()+"   Diverter: "+menu.diverter(),12,100,0xFFE5E9F0,false);g.text(font,"Scan: "+menu.scanMs()+" ms   scans: "+menu.scans()+"   items: "+menu.itemCount(),12,116,0xFFFFD166,false);g.text(font,"Route outcome code: "+menu.outcome(),12,160,0xFF76E5D8,false);}}
